UPDATE idtable SET value = 62685 WHERE id = 1;
-- 09: опытные поля Омского аграрного научного центра (ФГБНУ «Омский АНЦ»,
-- экс-СибНИИСХ; главная площадка — пр. Академика Королёва, пос. СИБНИИСХОЗ,
-- опытное поле — филиал «Омское», пос. Большие Поля). Геометрия — реальные
-- угодья OpenStreetMap на фактических местах (way id: 283140363, 283140365, 1564314633, 1564314631, 1392052662):
-- опытные поля у главной площадки + селекционные массивы к востоку от Омска.
-- Площади = площади контуров; культуры — демонстрационные (селекционные
-- направления АНЦ: зерновые, рапс, картофель); агрохимия — типичные значения
-- чернозёмов южной лесостепи Омского Прииртышья.
